export function FieldRenderer<TFormValues extends FormedibleFormValues>(props: FormedibleFieldRenderProps<TFormValues>) {
  const FieldComponent = props.fieldConfig.component ?? props.defaultComponent ?? getFieldComponent<TFormValues>(props.fieldConfig.type);
  const FieldWrapper = props.fieldConfig.wrapper;
  const GlobalWrapper = props.globalWrapper;
  const fieldElement = <FieldComponent fieldConfig={props.fieldConfig} field={props.field} renderField={props.renderField} />;
  const wrappedField = FieldWrapper ? (
    <FieldWrapper fieldConfig={props.fieldConfig} field={props.field}>
      {fieldElement}
    </FieldWrapper>
  ) : (
    fieldElement
  );

  return GlobalWrapper ? (
    <GlobalWrapper fieldConfig={props.fieldConfig} field={props.field}>
      {wrappedField}
    </GlobalWrapper>
  ) : (
    wrappedField
  );
}

import type { ReactNode } from 'react';

import { Field, FieldDescription, FieldError, FieldLabel } from '@/components/ui/field';
import type { FormedibleFieldController, FormedibleFormValues, FormedibleHelpConfig, NormalizedFieldConfig } from '@/lib/formedible/types';

function isHelpConfig(help: ReactNode | FormedibleHelpConfig): help is FormedibleHelpConfig {
  return typeof help === 'object' && help !== null && ('tooltip' in help || 'text' in help);
}

function getHelpContent(help: NormalizedFieldConfig['help']): ReactNode {
  if (!help) {
    return undefined;
  }

  if (isHelpConfig(help)) {
    return help.tooltip ?? help.text;
  }

  return help;
}

export interface FieldWrapperProps<TFormValues extends FormedibleFormValues = FormedibleFormValues> {
  readonly fieldConfig: NormalizedFieldConfig<TFormValues>;
  readonly field: FormedibleFieldController;
  readonly children: ReactNode;
}

export function FieldWrapper<TFormValues extends FormedibleFormValues>({ fieldConfig, field, children }: FieldWrapperProps<TFormValues>) {
  const helpContent = getHelpContent(fieldConfig.help);

  return (
    <Field
      className={fieldConfig.className}
      data-disabled={fieldConfig.disabled ? 'true' : undefined}
      data-invalid={field.error ? 'true' : undefined}
      onFocusCapture={field.onFocus}
    >
      {fieldConfig.label ? (
        <FieldLabel htmlFor={field.id}>
          {fieldConfig.label}
          {fieldConfig.required ? <span aria-hidden="true"> *</span> : undefined}
        </FieldLabel>
      ) : undefined}
      {children}
      {fieldConfig.description ? <FieldDescription>{fieldConfig.description}</FieldDescription> : undefined}
      {helpContent ? <FieldDescription>{helpContent}</FieldDescription> : undefined}
      {field.error ? <FieldError>{field.error}</FieldError> : undefined}
    </Field>
  );
}

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Input as TextInput } from '@/components/ui/input';
import type { FormedibleFieldOption, FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

const textInputTypes = ['email', 'password', 'url', 'tel'] as const;

function getInputType(type: string) {
  return textInputTypes.some((inputType) => inputType === type) ? type : 'text';
}

function hasDatalistOptions(options: readonly FormedibleFieldOption[] | undefined): options is readonly FormedibleFieldOption[] {
  return Array.isArray(options) && options.length > 0;
}

function renderDatalistOptions(id: string, options: readonly FormedibleFieldOption[] | undefined) {
  if (!hasDatalistOptions(options)) {
    return undefined;
  }

  return (
    <datalist id={id}>
      {options.map((option) => {
        if (typeof option === 'string') {
          return <option key={option} value={option} />;
        }

        return (
          <option key={option.value} value={option.value} disabled={option.disabled}>
            {option.label}
          </option>
        );
      })}
    </datalist>
  );
}

export function TextField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const value = typeof field.value === 'string' ? field.value : '';
  const datalistId = `${field.id}-datalist`;

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <TextInput
        id={field.id}
        name={field.name}
        type={getInputType(fieldConfig.type)}
        value={value}
        placeholder={fieldConfig.placeholder}
        list={hasDatalistOptions(fieldConfig.datalist) ? datalistId : undefined}
        disabled={fieldConfig.disabled}
        required={fieldConfig.required}
        aria-invalid={field.error ? true : undefined}
        className={fieldConfig.inputClassName}
        onBlur={field.onBlur}
        onChange={(event) => field.onChange(event.target.value)}
      />
      {renderDatalistOptions(datalistId, fieldConfig.datalist)}
    </FieldWrapper>
  );
}

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Input } from '@/components/ui/input';
import type { FormedibleFieldRenderProps, FormedibleFormValues, FormedibleMaskedInputConfig, FormedibleMaskedInputMask } from '@/lib/formedible/types';

const digitMaskToken = '9';
const legacyDigitMaskToken = '0';
const alphaMaskToken = 'a';
const upperAlphaMaskToken = 'A';
const alphaNumericMaskToken = '*';
const maskGuideCharacter = '_';

export function MaskedField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const rawValue = typeof field.value === 'string' ? field.value : '';
  const maskedInputConfig = fieldConfig.maskedInputConfig;
  const mask = fieldConfig.mask ?? maskedInputConfig?.mask;
  const value = mask ? applyInputMask(rawValue, mask, maskedInputConfig) : rawValue;
  const placeholder = getMaskedInputPlaceholder(fieldConfig.placeholder, maskedInputConfig);

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <Input
        data-slot="masked-input"
        data-mask={typeof mask === 'string' ? mask : undefined}
        id={field.id}
        name={field.name}
        type="text"
        inputMode={typeof mask === 'string' && usesOnlyDigitTokens(mask) ? 'numeric' : undefined}
        value={value}
        placeholder={placeholder}
        disabled={fieldConfig.disabled}
        required={fieldConfig.required}
        aria-invalid={field.error ? true : undefined}
        className={fieldConfig.inputClassName}
        onBlur={field.onBlur}
        onChange={(event) => field.onChange(mask ? applyInputMask(event.target.value, mask, maskedInputConfig, value) : event.target.value)}
      />
    </FieldWrapper>
  );
}

function applyInputMask(value: string, mask: FormedibleMaskedInputMask, config?: FormedibleMaskedInputConfig, fallbackValue = ''): string {
  if (typeof mask === 'function') {
    return applyMaskPipe(mask(value), config, fallbackValue);
  }

  let valueIndex = 0;
  let maskedValue = '';

  for (const maskCharacter of mask) {
    const matcher = getMaskTokenMatcher(maskCharacter);

    if (!matcher) {
      maskedValue += maskCharacter;
      continue;
    }

    const nextValueCharacter = getNextMatchingCharacter(value, valueIndex, matcher);
    if (!nextValueCharacter && shouldShowGuide(config)) {
      maskedValue += maskGuideCharacter;
      continue;
    }

    if (!nextValueCharacter) {
      break;
    }

    maskedValue += getConformedMaskCharacter(nextValueCharacter.character, maskCharacter);
    valueIndex = nextValueCharacter.nextIndex;
  }

  return applyMaskPipe(maskedValue, config, fallbackValue);
}

function getNextMatchingCharacter(
  value: string,
  startIndex: number,
  matcher: (character: string) => boolean,
): { readonly character: string; readonly nextIndex: number } | undefined {
  for (let index = startIndex; index < value.length; index += 1) {
    const character = value[index];

    if (character && matcher(character)) {
      return { character, nextIndex: index + 1 };
    }
  }

  return undefined;
}

function getMaskTokenMatcher(token: string): ((character: string) => boolean) | undefined {
  if (token === digitMaskToken || token === legacyDigitMaskToken) {
    return (character) => /\d/.test(character);
  }

  if (token === alphaMaskToken || token === upperAlphaMaskToken) {
    return (character) => /[A-Za-z]/.test(character);
  }

  if (token === alphaNumericMaskToken) {
    return (character) => /[A-Za-z0-9]/.test(character);
  }

  return undefined;
}

function usesOnlyDigitTokens(mask: string): boolean {
  return [...mask].some((character) => character === digitMaskToken || character === legacyDigitMaskToken) && [...mask].every((character) => character === digitMaskToken || character === legacyDigitMaskToken || !getMaskTokenMatcher(character));
}

function getConformedMaskCharacter(character: string, token: string): string {
  if (token === upperAlphaMaskToken) {
    return character.toUpperCase();
  }

  if (token === alphaMaskToken) {
    return character.toLowerCase();
  }

  return character;
}

function shouldShowGuide(config: FormedibleMaskedInputConfig | undefined): boolean {
  return config?.showMask === true && config.guide !== false;
}

function applyMaskPipe(maskedValue: string, config: FormedibleMaskedInputConfig | undefined, fallbackValue: string): string {
  if (!config?.pipe) {
    return maskedValue;
  }

  const pipedValue = config.pipe(maskedValue, config);

  if (pipedValue === false) {
    return fallbackValue;
  }

  if (typeof pipedValue === 'string') {
    return pipedValue;
  }

  return pipedValue.value;
}

function getMaskedInputPlaceholder(fieldPlaceholder: string | undefined, config: FormedibleMaskedInputConfig | undefined): string | undefined {
  if (fieldPlaceholder) {
    return fieldPlaceholder;
  }

  if (config?.placeholder) {
    return config.placeholder;
  }

  if (typeof config?.mask === 'string' && shouldShowGuide(config)) {
    return config.mask.replace(/[09Aa*]/g, maskGuideCharacter);
  }

  return undefined;
}

import { useState } from 'react';

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Button } from '@/components/ui/button';
import { Input as TextInput } from '@/components/ui/input';
import { cn } from '@/lib/utils';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

const maximumPasswordStrength = 4;

function clampStrength(value: number) {
  if (!Number.isFinite(value)) {
    return 0;
  }

  return Math.min(maximumPasswordStrength, Math.max(0, Math.trunc(value)));
}

function getPasswordStrength(value: string) {
  const lengthScore = value.length >= 12 ? 1 : 0;
  const lowercaseScore = /[a-z]/u.test(value) ? 1 : 0;
  const uppercaseScore = /[A-Z]/u.test(value) ? 1 : 0;
  const numberOrSymbolScore = /(?:\d|[^A-Za-z0-9])/u.test(value) ? 1 : 0;

  return lengthScore + lowercaseScore + uppercaseScore + numberOrSymbolScore;
}

function getStrengthLabel(strength: number) {
  if (strength <= 1) {
    return 'Weak';
  }

  if (strength === 2) {
    return 'Fair';
  }

  if (strength === 3) {
    return 'Good';
  }

  return 'Strong';
}

export function PasswordField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const [isVisible, setIsVisible] = useState(false);
  const value = typeof field.value === 'string' ? field.value : '';
  const strength = getPasswordStrength(value);
  const minStrength = clampStrength(fieldConfig.passwordConfig?.minStrength ?? 0);
  const showToggle = fieldConfig.passwordConfig?.showToggle === true;
  const showStrengthMeter = fieldConfig.passwordConfig?.strengthMeter === true;
  const inputType = showToggle && isVisible ? 'text' : 'password';

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <div className="relative">
        <TextInput
          id={field.id}
          name={field.name}
          type={inputType}
          value={value}
          placeholder={fieldConfig.placeholder}
          disabled={fieldConfig.disabled}
          required={fieldConfig.required}
          aria-invalid={field.error ? true : undefined}
          className={cn(showToggle ? 'pr-24' : undefined, fieldConfig.inputClassName)}
          onBlur={field.onBlur}
          onChange={(event) => field.onChange(event.target.value)}
        />
        {showToggle ? (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            aria-label={isVisible ? 'Hide password' : 'Show password'}
            aria-pressed={isVisible}
            className="absolute top-1/2 right-1 h-7 -translate-y-1/2 px-2"
            disabled={fieldConfig.disabled}
            onClick={() => setIsVisible((current) => !current)}
          >
            {isVisible ? 'Hide' : 'Show'}
          </Button>
        ) : null}
      </div>
      {showStrengthMeter ? (
        <div className="space-y-1" aria-live="polite">
          <div className="bg-muted flex h-2 overflow-hidden rounded-full" aria-hidden="true">
            <div className="bg-primary transition-all" style={{ width: `${(strength / maximumPasswordStrength) * 100}%` }} />
          </div>
          <p className="text-muted-foreground text-xs">
            Password strength: {getStrengthLabel(strength)} ({strength}/{maximumPasswordStrength})
            {minStrength > 0 ? ` · Minimum strength: ${minStrength}/${maximumPasswordStrength}` : null}
          </p>
        </div>
      ) : null}
    </FieldWrapper>
  );
}

