  switch (type) {
    case 'multiselect':
      return 'multiSelect';
    case 'multicombobox':
      return 'multiCombobox';
    case 'colorPicker':
      return 'color';
    case 'maskedInput':
      return 'masked';
    default:
      return type;
  }
}

